<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class AcademicPeriodController extends Controller {
 public function select(Request $r){$d=$r->validate(['academic_period_id'=>'required|integer']);abort_unless(DB::table('academic_periods')->where('id',$d['academic_period_id'])->exists(),404);$r->session()->put('academic_period_id',(int)$d['academic_period_id']);return back();}
 public function close(Request $r,$id){abort_unless($r->user()->canDo('periods.close'),403);$lessons=DB::table('lesson_occurrences')->where('academic_period_id',$id)->where('status','!=','cancelled')->get(['id','topic']);$missingTopic=$lessons->whereNull('topic')->count();$withAttendance=DB::table('attendance_records')->whereIn('lesson_occurrence_id',$lessons->pluck('id'))->distinct()->count('lesson_occurrence_id');$missingAttendance=max(0,$lessons->count()-$withAttendance);$openNotes=DB::table('journal_review_notes')->where(['academic_period_id'=>$id,'status'=>'open'])->count();if(($missingTopic+$missingAttendance+$openNotes)>0&&!$r->boolean('force'))return back()->withErrors(['period'=>"Период не закрыт: без темы — $missingTopic занятий; без посещаемости — $missingAttendance; открытых замечаний — $openNotes."]);if($r->boolean('force')){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('head_academic'),403);$r->validate(['force_reason'=>'required|string|min:10|max:2000']);}DB::table('academic_periods')->where('id',$id)->update(['is_closed'=>true,'updated_at'=>now()]);return back()->with('success','Период закрыт. Журнал переведён в архивный режим.');}
 public function open(Request $r,$id){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('head_academic'),403);DB::table('academic_periods')->where('id',$id)->update(['is_closed'=>false,'updated_at'=>now()]);return back()->with('success','Период открыт.');}
}
